<?php
namespace App\Modules\Orders\Presentation\Http\Controllers;
use App\Http\Controllers\Controller;use App\Modules\Identity\Domain\Models\AuthorizationRequest;use App\Modules\Orders\Application\ConfirmSalesOrder;use App\Modules\Orders\Application\Data\OrderLineData;use App\Modules\Orders\Application\Data\SalesOrderData;use App\Modules\Orders\Application\SaveDraftOrder;use App\Modules\Orders\Domain\Enums\OrderPriority;use App\Modules\Orders\Domain\Models\SalesOrder;use App\Modules\Orders\Presentation\Http\Requests\SaveSalesOrderRequest;use Illuminate\Http\RedirectResponse;use Illuminate\Support\Carbon;
class UpdateSalesOrderController extends Controller {public function __invoke(SaveSalesOrderRequest $request,SalesOrder $order,SaveDraftOrder $save,ConfirmSalesOrder $confirm):RedirectResponse{$d=$request->validated();$auth=isset($d['price_authorization_id'])?AuthorizationRequest::findOrFail($d['price_authorization_id']):null;$order=$save->execute(new SalesOrderData($d['customer_profile_id'],$d['price_list_id'],Carbon::parse($d['ordered_at']),Carbon::parse($d['due_at']),OrderPriority::from($d['priority']),(int)$d['discount'],$d['notes']??null,$request->user(),array_map(OrderLineData::fromArray(...),$d['lines']),$auth),$order);if($d['confirm']??false)$confirm->execute($order,$request->user());return to_route('orders.show',$order)->with('success','Pedido actualizado.');}}
